def interval_intersection(first_list, second_list):
    result = []
    i, j = 0, 0

    while i < len(first_list) and j < len(second_list):
        start1, end1 = first_list[i]
        start2, end2 = second_list[j]

        lo = max(start1, start2)
        hi = min(end1, end2)
        if lo <= hi:
            result.append([lo, hi])

        if end1 < end2:
            i += 1
        else:
            j += 1

    return result

